      "source": "\u003c?xml version=\"1.0\" encoding=\"UTF-8\"?>\n\u003cScheme LastUpgradeVersion=\"2700\" version=\"1.3\">\n    \u003cBuildAction parallelizeBuildables=\"YES\" buildImplicitDependencies=\"YES\">\u003cBuildActionEntries>\n        \u003cBuildActionEntry buildForTesting=\"YES\" buildForRunning=\"YES\" buildForProfiling=\"YES\" buildForArchiving=\"YES\" buildForAnalyzing=\"YES\">\n            \u003cBuildableReference BuildableIdentifier=\"primary\" BlueprintIdentifier=\"A50000000000000000000001\" BuildableName=\"SwiftUIWorkbench.app\" BlueprintName=\"SwiftUIWorkbench\" ReferencedContainer=\"container:SwiftUIWorkbench.xcodeproj\"/>\n        \u003c/BuildActionEntry>\n    \u003c/BuildActionEntries>\u003c/BuildAction>\n    \u003cTestAction buildConfiguration=\"Debug\" selectedDebuggerIdentifier=\"Xcode.DebuggerFoundation.Debugger.LLDB\" selectedLauncherIdentifier=\"Xcode.IDEFoundation.Launcher.LLDB\" shouldUseLaunchSchemeArgsEnv=\"YES\"/>\n    \u003cLaunchAction buildConfiguration=\"Debug\" selectedDebuggerIdentifier=\"Xcode.DebuggerFoundation.Debugger.LLDB\" selectedLauncherIdentifier=\"Xcode.IDEFoundation.Launcher.LLDB\" launchStyle=\"0\" useCustomWorkingDirectory=\"NO\" ignoresPersistentStateOnLaunch=\"NO\" debugDocumentVersioning=\"YES\" debugServiceExtension=\"internal\" allowLocationSimulation=\"YES\">\n        \u003cBuildableProductRunnable runnableDebuggingMode=\"0\">\u003cBuildableReference BuildableIdentifier=\"primary\" BlueprintIdentifier=\"A50000000000000000000001\" BuildableName=\"SwiftUIWorkbench.app\" BlueprintName=\"SwiftUIWorkbench\" ReferencedContainer=\"container:SwiftUIWorkbench.xcodeproj\"/>\u003c/BuildableProductRunnable>\n    \u003c/LaunchAction>\n    \u003cProfileAction buildConfiguration=\"Release\" shouldUseLaunchSchemeArgsEnv=\"YES\" savedToolIdentifier=\"\" useCustomWorkingDirectory=\"NO\" debugDocumentVersioning=\"YES\">\u003cBuildableProductRunnable runnableDebuggingMode=\"0\">\u003cBuildableReference BuildableIdentifier=\"primary\" BlueprintIdentifier=\"A50000000000000000000001\" BuildableName=\"SwiftUIWorkbench.app\" BlueprintName=\"SwiftUIWorkbench\" ReferencedContainer=\"container:SwiftUIWorkbench.xcodeproj\"/>\u003c/BuildableProductRunnable>\u003c/ProfileAction>\n    \u003cAnalyzeAction buildConfiguration=\"Debug\"/>\n    \u003cArchiveAction buildConfiguration=\"Release\" revealArchiveInOrganizer=\"YES\"/>\n\u003c/Scheme>\n",
