  "syntax": [
    {
      "idea": "Immutable binding",
      "android": "val name = \"Ada\"",
      "swift": "let name = \"Ada\""
    },
    {
      "idea": "Mutable binding",
      "android": "var count = 0",
      "swift": "var count = 0"
    },
    {
      "idea": "Optional / fallback",
      "android": "name: String?; name ?: \"Unknown\"",
      "swift": "name: String?; name ?? \"Unknown\""
    },
    {
      "idea": "Optional binding",
      "android": "name?.let { value -> ... }",
      "swift": "if let value = name { ... }"
    },
    {
      "idea": "Early optional exit",
      "android": "val name = raw ?: return",
      "swift": "guard let name = raw else { return }"
    },
    {
      "idea": "List / array",
      "android": "List\u003cString>; listOf(\"A\")",
      "swift": "[String]; [\"A\"]"
    },
    {
      "idea": "Map / dictionary",
      "android": "Map\u003cString, Int>",
      "swift": "[String: Int]"
    },
    {
      "idea": "Function",
      "android": "fun count(value: Int): String",
      "swift": "func count(value: Int) -> String"
    },
    {
      "idea": "No external argument label",
      "android": "count(3)",
      "swift": "func count(_ value: Int); count(3)"
    },
    {
      "idea": "Function value",
      "android": "(String) -> Unit",
      "swift": "(String) -> Void"
    },
    {
      "idea": "Lambda parameter",
      "android": "{ name -> name.uppercase() }",
      "swift": "{ name in name.uppercased() }"
    },
    {
      "idea": "String interpolation",
      "android": "\"Name: $name\"",
      "swift": "\"Name: \\(name)\""
    },
    {
      "idea": "Protocol / interface",
      "android": "class Fake : Service",
      "swift": "struct Fake: Service"
    },
    {
      "idea": "Sealed-case matching",
      "android": "when (state) { is Loaded -> ... }",
      "swift": "switch state { case let .loaded(items): ... }"
    },
    {
      "idea": "Error handling",
      "android": "try { load() } catch (e: Exception) { ... }",
      "swift": "do { try load() } catch { ... }"
    },
    {
      "idea": "Suspending call",
      "android": "suspend fun load(); load()",
      "swift": "func load() async; await load()"
    },
    {
      "idea": "Suspension + failure",
      "android": "suspend call can throw",
      "swift": "func load() async throws; try await load()"
    },
    {
      "idea": "Class identity",
      "android": "first === second",
      "swift": "first === second"
    },
    {
      "idea": "Value equality",
      "android": "first == second",
      "swift": "first == second // requires Equatable"
    },
    {
      "idea": "Weak observation",
      "android": "WeakReference(instance).get()",
      "swift": "weak var instance: SomeClass?"
    },
    {
      "idea": "Named member access",
      "android": "this.name",
      "swift": "self.name"
    },
    {
      "idea": "Superclass initialization",
      "android": "constructor(...) : super(...)",
      "swift": "init(...) { ...; super.init(...) }"
    }
  ],
